output:
.saved {
  display: inline-block;
  animation: saved-enter 180ms ease-out both;
}

@keyframes saved-enter {
  from {
    opacity: 0;
    transform: translateY(2px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .saved {
    animation: none;
  }
}
